package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.SeguridadInstitucional;import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.nucleo.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.file.*;import java.util.*;import java.io.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.SpringBootConfiguration;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.mock.env.MockEnvironment;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=DocumentalHttpTest.Application.class,properties={"institucional.nucleo.habilitado=true","institucional.formulario-completo.habilitado=true","institucional.documental.habilitada=true","institucional.nucleo.password-laboratorio=SoloPruebasSinteticasClaveDeMasDe32Caracteres"})
@AutoConfigureMockMvc @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class DocumentalHttpTest {
 @SpringBootConfiguration @EnableAutoConfiguration @Import({SeguridadInstitucional.class,DocumentosGestionController.class,DocumentosIngresoController.class,ErroresTecnicos.class,JsonEstricto.class,Fixture.class}) static class Application{}
 @Configuration static class Fixture {
  @Bean(destroyMethod="close") DatosDocumentalesTest datos()throws Exception{return new DatosDocumentalesTest(Files.createTempDirectory("documental-http-"));}
  @Bean HabilitacionNucleo gate(){var e=new MockEnvironment().withProperty("institucional.nucleo.habilitado","true").withProperty("institucional.nucleo.entorno","LABORATORIO").withProperty("server.address","127.0.0.1").withProperty("datos.mysql-local","true").withProperty("server.servlet.session.cookie.secure","true").withProperty("institucional.db.url","jdbc:mysql://127.0.0.1:13306/robust_inst_test?sslMode=DISABLED");e.setActiveProfiles("nucleo-lab","jdbc-reception");return new HabilitacionNucleo(e);}
  @Bean CatalogoLaboratorio catalog(DatosDocumentalesTest x){return x.d.catalog;}@Bean NucleoInstitucional core(DatosDocumentalesTest x){return x.d.core;}@Bean(destroyMethod="") BaseJdbc db(DatosDocumentalesTest x){return x.d.db;}@Bean(destroyMethod="") ArchivoInstitucional files(DatosDocumentalesTest x){return x.d.files;}@Bean RecepcionInstitucionalJdbc receiver(DatosDocumentalesTest x){return x.d.receiver;}@Bean AutorizacionDocumental policy(DatosDocumentalesTest x){return x.policy;}@Bean DocumentosGestion gestion(DatosDocumentalesTest x){return x.gestion;}@Bean VisorDocumento visor(DatosDocumentalesTest x){return x.visor;}
 }
 @Autowired MockMvc http;@Autowired DatosDocumentalesTest x;
 String url(){return "/nucleo/casos/"+x.uno+"/documentos-gestion";}
 MockMultipartFile archivo(){return new MockMultipartFile("archivo","sintetico.pdf","text/html",x.contenido);}
 UUID cargar()throws Exception{var response=http.perform(multipart(url()).file(archivo()).param("actuacion",x.actuacion.toString()).secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isOk()).andExpect(jsonPath("$.origen").value("GESTION_INSTITUCIONAL")).andExpect(jsonPath("$.autor").value("demo.profesional.upr.a")).andExpect(jsonPath("$.tipo").value("application/pdf")).andReturn();return UUID.fromString(x.d.mapper.readTree(response.getResponse().getContentAsString()).path("id").asString());}
 @Test void cargaExigeSesionHttpsCsrfYAlcance()throws Exception{
  http.perform(multipart(url()).file(archivo()).secure(true).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isUnauthorized());
  http.perform(multipart(url()).file(archivo()).secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isForbidden());
  http.perform(multipart(url()).file(archivo()).with(csrf().asHeader()).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isForbidden());
  http.perform(multipart(url()).file(archivo()).secure(true).with(csrf().asHeader()).with(user("demo.profesional.upd.a").roles("FUNCIONARIO_LAB")).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isNotFound());
 }
 @Test void origenAutorYHashNoSonEtiquetasDelCliente()throws Exception{for(var param:List.of("origen","autor","sha256"))http.perform(multipart(url()).file(archivo()).param(param,"manipulado").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isBadRequest());}
 @Test void pdfSePrevisualizaPorPngYOriginalSoloSeDescarga()throws Exception{
  var id=cargar();var base=url()+"/"+id;
  http.perform(get(base+"/historial").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isOk()).andExpect(jsonPath("$[0].tipo").value("DOCUMENTO_CREADO"));
  http.perform(get(base+"/vista").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isOk()).andExpect(jsonPath("$.paginas").value(3)).andExpect(jsonPath("$.originalInline").value(false));
  var response=http.perform(get(base+"/paginas/2").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(request().asyncStarted()).andReturn();http.perform(asyncDispatch(response)).andExpect(status().isOk()).andExpect(content().contentType("image/png")).andExpect(header().string("Cache-Control","no-store"));
  http.perform(head(base+"/paginas/1").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isOk()).andExpect(content().string(""));
  http.perform(get(base+"/representacion").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isNotFound());
  var original=http.perform(get(base+"/original").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andReturn();http.perform(asyncDispatch(original)).andExpect(status().isOk()).andExpect(content().contentType("application/octet-stream")).andExpect(content().bytes(x.contenido));
 }
 @Test void otroCasoOtraUnidadOSinSesionNoObtienenPaginas()throws Exception{var id=cargar();var base=url()+"/"+id;http.perform(get(base+"/paginas/1").secure(true)).andExpect(status().isUnauthorized());http.perform(get(base+"/paginas/1").secure(true).with(user("demo.profesional.upd.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isNotFound());http.perform(get("/nucleo/casos/"+x.dos+"/documentos-gestion/"+id+"/original").secure(true).with(user("demo.jefatura.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isNotFound());}
 @Test void ingresoHistorico10Y11AdmitenPaginasSinAlterarFirma()throws Exception{
  for(String version:List.of("1.0","1.1")){var attachment=new EntregaCompleta.Adjunto(UUID.randomUUID(),"historico.bin",x.contenido.length,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(x.contenido)),"application/pdf","VALIDADO");var e=x.d.delivery(version,"NNA",List.of(attachment),false,1);x.d.files.guardar(e.id(),attachment,new ByteArrayInputStream(x.contenido));var ack=x.d.receiver.guardarCompleta(e,x.d.files);var com=ack.registro().comunicacionId();var id=x.d.db.sql.queryForObject("SELECT id FROM institution_document WHERE communication_id=? AND origin='INGRESO_CIUDADANO'",String.class,com.toString());var base="/nucleo/comunicaciones/"+com+"/documentos/"+id;
   http.perform(get(base+"/vista").secure(true).with(user("demo.distribucion").roles("FUNCIONARIO_LAB"))).andExpect(status().isOk()).andExpect(jsonPath("$.paginas").value(3));
   var page=http.perform(get(base+"/paginas/2").secure(true).with(user("demo.distribucion").roles("FUNCIONARIO_LAB"))).andReturn();http.perform(asyncDispatch(page)).andExpect(status().isOk()).andExpect(content().contentType("image/png"));
   http.perform(get(base+"/representacion").secure(true).with(user("demo.distribucion").roles("FUNCIONARIO_LAB"))).andExpect(status().isNotFound());http.perform(post(url()+"/"+id+"/vinculos").secure(true).with(user("demo.jefatura.upr.a").roles("FUNCIONARIO_LAB")).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(x.d.mapper.writeValueAsString(Map.of("casoOrigen",x.uno)))).andExpect(status().isNotFound());assertEquals(x.d.mapper.writeValueAsString(e),x.d.mapper.writeValueAsString(x.d.receiver.completaRegistrada(com)));
  }
 }
 @Test void paginaFueraDeRangoYArchivoAlteradoDanErroresControlados()throws Exception{var id=cargar();var base=url()+"/"+id;http.perform(get(base+"/paginas/4").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isNotFound());var ref=x.gestion.referencia(x.d.catalog.operador("demo.profesional.upr.a"),x.uno,id);Files.writeString(x.gestion.verificarArchivo(ref),"ALTERADO");http.perform(get(base+"/original").secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB"))).andExpect(status().isConflict());}
 @Test void multipartVacioOExcedidoNuncaSeLeeComoArchivoValido()throws Exception{
  http.perform(multipart(url()).file(new MockMultipartFile("archivo","vacio.pdf","application/pdf",new byte[0])).secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isUnprocessableEntity());
  var large=new MockMultipartFile("archivo","grande.pdf","application/pdf",new byte[1]){@Override public long getSize(){return FormatosDocumento.MAX+1;}};http.perform(multipart(url()).file(large).secure(true).with(user("demo.profesional.upr.a").roles("FUNCIONARIO_LAB")).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isContentTooLarge());
 }
}